public static class Command{public static string Run(){var f=BindingFlags.Static|BindingFlags.NonPublic;var guest=(Pawn)Host.State["guest"];var b=(Thing)Host.State["chess"];var game=b.TryGetComp<CompMiniGame>().Game;var map=b.Map;var comp=GameComponent_Recreation.Current;var sb=new System.Text.StringBuilder();PRMod.Settings.playTogether=true;TogetherInvite.Reset();guest.jobs.EndCurrentJob(JobCondition.InterruptForced);guest.jobs.TryTakeOrderedJob(JobMaker.MakeJob(JobDefOf.Wait_Wander,1000),JobTag.Misc);guest.Position=b.Position+new IntVec3(0,0,-2);guest.Notify_Teleported();var sess=comp.SessionFor(b);if(sess!=null)comp.Remove(sess);guest.mindState.duty=new PawnDuty(DefDatabase<DutyDef>.GetNamed("ExitMapRandom"));typeof(TogetherInvite).GetMethod("CollectGuests",f).Invoke(null,new object[]{map,b,game});var guests=(List<Pawn>)typeof(TogetherInvite).GetField("tmpGuests",f).GetValue(null);sb.AppendLine("leaving duty excluded="+!guests.Contains(guest));guest.mindState.duty=new PawnDuty(DutyDefOf.Defend,b.Position);guest.jobs.EndCurrentJob(JobCondition.InterruptForced);guest.jobs.TryTakeOrderedJob(JobMaker.MakeJob(JobDefOf.Wait_Wander,1000),JobTag.Misc);bool invited=(bool)typeof(TogetherInvite).GetMethod("Invite",f).Invoke(null,new object[]{game,b,guest});sb.AppendLine("direct debug invite="+invited);typeof(TogetherInvite).GetMethod("CollectGuests",f).Invoke(null,new object[]{map,b,game});sb.AppendLine("already waiting guest excluded="+!guests.Contains(guest));typeof(TogetherInvite).GetMethod("CollectBoards",f).Invoke(null,new object[]{map});var boards=(List<Thing>)typeof(TogetherInvite).GetField("tmpBoards",f).GetValue(null);sb.AppendLine("waiting board excluded="+!boards.Contains(b));TogetherInvite.Reset();guest.jobs.EndCurrentJob(JobCondition.InterruptForced);var p=((Pawn[])Host.State["punchPair"])[0];p.jobs.EndCurrentJob(JobCondition.InterruptForced);var job=JobMaker.MakeJob(game.vanillaJob,b);bool reserved=p.Reserve(b,job,Together.SeatCount(game));typeof(TogetherInvite).GetMethod("CollectBoards",f).Invoke(null,new object[]{map});sb.AppendLine("colonist reserved="+reserved+" board excluded="+!boards.Contains(b));map.reservationManager.ReleaseAllForTarget(b);var fac=guest.Faction;var guestsOfFaction=map.mapPawns.SpawnedPawnsInFaction(fac).ToList();comp.SetGoodwillApplied(fac,4);foreach(var q in guestsOfFaction)q.DeSpawn();typeof(GameComponent_Recreation).GetMethod("ForgetEndedVisits",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(comp,null);sb.AppendLine("all faction pawns map-exit applied cleared="+(comp.GoodwillApplied(fac)==0));foreach(var q in guestsOfFaction)GenSpawn.Spawn(q,b.Position+new IntVec3(0,0,-3),map);var scale=typeof(TogetherGoodwill).GetMethod("Scale",f);sb.AppendLine("tier0 ordinary/close/crushed scaled="+scale.Invoke(null,new object[]{4,game,0,100})+","+scale.Invoke(null,new object[]{8,game,0,100})+","+scale.Invoke(null,new object[]{-6,game,0,100})+" (runtime calculation only)");Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;return sb.ToString();}}
